package EmployeeManagementSystem.entity;
import jakarta.persistence.*; import lombok.Data; import java.time.*;
@Entity @Table(name="shift_assignments", uniqueConstraints=@UniqueConstraint(columnNames={"employee_id","shift_date"})) @Data public class ShiftAssignment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="employee_id",nullable=false) private Employee employee; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="shift_id",nullable=false) private Shift shift; @Column(name="shift_date",nullable=false) private LocalDate shiftDate; private String status="SCHEDULED"; private Double overtimeHours=0.0; private String notes; private String swapStatus="NONE"; private LocalDateTime createdAt=LocalDateTime.now(); }
